('108-4301-066','108-4301',66,'single_choice',2,'When a judicial decision cannot have any practical legal effect because the issues that generated it either have been resolved or disappeared, it is said that the case has become .','removable','moot','undecided','reserved',null,'法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
